//! Protobuf messages of the Nocterm hub protocol, package `nocterm.hub.v1`.
//!
//! Owns: the generated `prost` messages, the encoded descriptor set and conversions between
//! wire enums and the neutral types of `nocterm-hub-model`.
//! Does not own: transport. gRPC stubs are generated by each transport crate from
//! [`FILE_DESCRIPTOR_SET`] with `extern_path(".nocterm.hub.v1", "::nocterm_hub_proto::v1")`,
//! so messages exist once and only transport crates depend on `tonic`.
//! Ports used/provided: none. Settings: none. Globals: none.
//! Invariants: `.proto` files evolve compatibly (fields and enum values are only added);
//! the baseline in `proto/baseline` is checked in CI.

#[allow(
    clippy::all,
    clippy::pedantic,
    missing_debug_implementations,
    reason = "generated code"
)]
pub mod v1 {
    include!(concat!(env!("OUT_DIR"), "/nocterm.hub.v1.rs"));
}

mod cloud_secrets;
mod convert;

pub use convert::{assurance_from_wire, assurance_to_wire, role_from_wire, role_to_wire};

/// Encoded `FileDescriptorSet` of every `.proto` file, for code generation and reflection.
pub const FILE_DESCRIPTOR_SET: &[u8] =
    include_bytes!(concat!(env!("OUT_DIR"), "/hub_v1_descriptor.bin"));
